import math

import pytest

from vultr_model_catalog import ModelPricing, ReasoningSupport, normalize_model, parse_catalog, usd_per_million


def models(payload):
    return [normalize_model(document) for document in parse_catalog(payload).documents]


# The pinned output is generated by the TypeScript project (UPDATE_FIXTURES=1 npm test).
@pytest.mark.parametrize("name", ["vultr-catalog", "vultr-dev-catalog", "edge-cases"])
def test_matches_the_pinned_canonical_output(load, name):
    assert [model.to_dict() for model in models(load(f"{name}.json"))] == load(f"{name}.normalized.json")


def test_live_catalog_chat_model_fields_come_out_of_the_nested_modalities(load):
    model = next(m for m in models(load("vultr-catalog.json")) if m.id == "deepseek-v4-flash-0731")
    assert model.context_window == 1_048_576
    assert model.max_output_tokens == 1_048_576
    assert model.input_modalities == ["text", "image"]
    assert model.pricing.prompt == "0.0000001"
    assert model.pricing.completion == "0.00000025"
    assert model.price_per_million() == {
        "prompt": 0.1,
        "cached_prompt": None,
        "cache_write": None,
        "completion": 0.25,
        "internal_reasoning": None,
    }
    assert model.tools and model.streaming
    assert model.reasoning.supports_max_tokens is False
    assert model.reasoning.supported_efforts[0] == "ultra"
    assert model.accepts_input("image") and not model.accepts_input("video")
    assert "temperature" in model.parameters


def test_live_catalog_non_text_models_are_not_chat_models(load):
    everything = models(load("vultr-catalog.json"))
    skipped = [model.id for model in everything if not model.is_chat]
    for model_id in ["bge-reranker-v2-m3", "qwen3-embedding-4b", "z-image-turbo", "whisper-large-v3-turbo", "mica-v0.1-4b"]:
        assert model_id in skipped
    assert next(m for m in everything if m.id == "mica-v0.1-4b").output_modalities == ["decision"]
    assert all(model.context_window is not None for model in everything if model.is_chat)


def test_live_catalog_agent_models_are_the_chat_models_that_call_tools(load):
    everything = models(load("vultr-catalog.json"))
    classifier = next(m for m in everything if m.id == "nemotron-3.5-content-safety")
    assert classifier.is_chat
    assert classifier.tools is False
    assert not classifier.is_agent
    agents = [m for m in everything if m.is_agent]
    assert any(m.id == "deepseek-v4-flash-0731" for m in agents)
    assert all(m.is_chat and m.is_ready and m.tools and m.context_window is not None for m in agents)
    assert len(agents) == len([m for m in everything if m.is_chat]) - 1


def test_pricing_prefers_the_entry_without_a_utc_window(load):
    model = next(m for m in models(load("edge-cases.json")) if m.id == "windowed-pricing")
    assert model.pricing == ModelPricing(
        prompt="0.000001",
        cached_prompt="0.0000001",
        cache_write="0.00000125",
        completion="0.000003",
        internal_reasoning="0.000004",
        request="0.001",
    )
    assert model.max_prompt_tokens == 30_000
    assert model.structured_outputs is True
    assert model.streaming is False
    assert model.is_ready is False
    assert model.deprecation_date == "2027-01-01"
    assert model.reasoning == ReasoningSupport(
        mandatory=True,
        default_effort="medium",
        default_enabled=True,
        supported_efforts=["high", "medium", "low"],
        supports_max_tokens=True,
    )


def test_a_document_with_nothing_optional_still_normalizes(load):
    model = next(m for m in models(load("edge-cases.json")) if m.id == "bare-minimum")
    assert model.context_window is None
    assert model.max_output_tokens is None
    assert model.pricing == ModelPricing()
    assert model.reasoning is None
    assert model.tools is False
    assert model.is_ready is True
    assert model.is_chat
    assert not model.is_agent


def test_bad_entries_are_skipped_and_reported_not_fatal(load):
    parsed = parse_catalog(load("edge-cases.json"))
    assert [document["id"] for document in parsed.documents] == [
        "windowed-pricing",
        "bare-minimum",
        "future-schema",
        "params-capped-budget",
        "params-unrestricted-effort",
        "params-win-over-root",
        "params-effort-only",
        "params-unreadable-use-root",
        "decisions-modality",
    ]
    assert [(issue.index, issue.id) for issue in parsed.issues] == [
        (2, "future-schema"),
        (3, None),
        (4, "no-modalities"),
        (5, None),
    ]
    assert "parsed anyway" in parsed.issues[0].message


def test_parse_catalog_accepts_a_bare_list_and_rejects_anything_else():
    assert parse_catalog([]).documents == []
    with pytest.raises(TypeError):
        parse_catalog({"models": []})
    with pytest.raises(TypeError):
        parse_catalog(None)


def test_usd_per_million_is_exact():
    assert usd_per_million("0.0000001") == 0.1
    assert usd_per_million("0.00000025") == 0.25
    assert usd_per_million("0.00000005") == 0.05
    assert usd_per_million("0.000003") == 3
    assert usd_per_million("0.00000125") == 1.25
    assert usd_per_million("1") == 1_000_000
    assert usd_per_million("0") == 0
    assert usd_per_million(".5") == 500_000
    assert usd_per_million("2.5e-7") == 0.25
    assert math.isnan(usd_per_million("free"))


# The reasoning facts live in the text output's supported_parameters; the root reasoning object is a
# temporary extension. vultr-dev-catalog.json is a capture of dev's /v1/models, which carries both.
def reasoning_of(load, file, model_id):
    return next(m for m in models(load(file)) if m.id == model_id).reasoning


def without_root(document):
    return {key: value for key, value in document.items() if key != "reasoning"}


def without_parameters(document):
    outputs = []
    for modality in document["output_modalities"]:
        kept = {k: v for k, v in (modality.get("supported_parameters") or {}).items() if k not in ("reasoning", "reasoning_effort")}
        outputs.append({**modality, "supported_parameters": kept} if "supported_parameters" in modality else modality)
    return {**document, "output_modalities": outputs}


def test_dev_catalog_reasoning_comes_from_supported_parameters(load):
    flash = reasoning_of(load, "vultr-dev-catalog.json", "deepseek-v4-flash-0731")
    assert flash.supports_max_tokens is False
    assert flash.supported_efforts[0] == "ultra"
    assert reasoning_of(load, "vultr-dev-catalog.json", "deepseek-v4.1-flash").supports_max_tokens is True
    assert reasoning_of(load, "vultr-dev-catalog.json", "nemotron-3-nano-omni-30b-a3b-reasoning").supported_efforts == [
        "max",
        "xhigh",
        "high",
        "medium",
        "low",
        "minimal",
    ]
    assert reasoning_of(load, "vultr-dev-catalog.json", "nemotron-3.5-content-safety") is None


def test_dev_catalog_supported_parameters_alone_and_the_root_alone_give_the_same_reasoning(load):
    documents = parse_catalog(load("vultr-dev-catalog.json")).documents
    reasoning = [normalize_model(document).reasoning for document in documents]
    assert any(entry is not None for entry in reasoning)
    assert [normalize_model(without_root(document)).reasoning for document in documents] == reasoning
    assert [normalize_model(without_parameters(document)).reasoning for document in documents] == reasoning


def test_supported_parameters_give_the_efforts_and_whether_max_tokens_is_enforced(load):
    assert reasoning_of(load, "edge-cases.json", "params-capped-budget") == ReasoningSupport(
        mandatory=False,
        default_effort=None,
        default_enabled=None,
        supported_efforts=["high", "low"],
        supports_max_tokens=True,
    )


def test_reasoning_effort_of_unknown_type_means_no_effort_allowlist(load):
    reasoning = reasoning_of(load, "edge-cases.json", "params-unrestricted-effort")
    assert reasoning.supported_efforts is None
    assert reasoning.supports_max_tokens is False


def test_supported_parameters_win_over_the_root_which_still_gives_mandatory_and_the_defaults(load):
    assert reasoning_of(load, "edge-cases.json", "params-win-over-root") == ReasoningSupport(
        mandatory=True,
        default_effort="medium",
        default_enabled=True,
        supported_efforts=["medium", "low"],
        supports_max_tokens=False,
    )


def test_a_fact_the_parameters_do_not_state_comes_from_the_root(load):
    effort_only = reasoning_of(load, "edge-cases.json", "params-effort-only")
    assert effort_only.supported_efforts == ["high", "low"]
    assert effort_only.supports_max_tokens is True
    unreadable = reasoning_of(load, "edge-cases.json", "params-unreadable-use-root")
    assert unreadable.supported_efforts == ["high", "low"]
    assert unreadable.supports_max_tokens is True


def test_the_decisions_output_modality_is_not_a_chat_model(load):
    model = next(m for m in models(load("edge-cases.json")) if m.id == "decisions-modality")
    assert model.output_modalities == ["decisions"]
    assert not model.is_chat
    dev = [m for m in models(load("vultr-dev-catalog.json")) if "decisions" in m.output_modalities]
    assert dev and all(not m.is_chat for m in dev)
